"""TRF015: Models declaring tied weights need a tie_word_embeddings flag on their config."""

import ast
from pathlib import Path

from ._helpers import (
    Violation,
    _function_argument_names,
    _get_class_assignments,
    _is_direct_pretrained_config_subclass,
    _simple_name,
    full_name,
    iter_pretrained_classes,
)


RULE_ID = ""  # Set by discovery


def _has_nonempty_tied_weights_keys(class_node: ast.ClassDef) -> bool:
    """Whether the class declares a non-empty ``_tied_weights_keys`` literal."""
    value = _get_class_assignments(class_node).get("_tied_weights_keys")
    if value is None:
        return False
    if isinstance(value, (ast.List, ast.Tuple, ast.Set)):
        return len(value.elts) > 0
    if isinstance(value, ast.Dict):
        return len(value.keys) > 0
    if isinstance(value, ast.Constant):
        return bool(value.value)
    return False


def _annotation_name(annotation: ast.AST) -> str | None:
    try:
        return _simple_name(full_name(annotation))
    except ValueError:
        return None


def _config_annotation_name(class_node: ast.ClassDef) -> str | None:
    """Resolve a config class name from a ``config: SomeConfig`` annotation."""
    for item in class_node.body:
        if isinstance(item, ast.AnnAssign) and isinstance(item.target, ast.Name) and item.target.id == "config":
            return _annotation_name(item.annotation)

    for item in class_node.body:
        if isinstance(item, ast.FunctionDef) and item.name == "__init__":
            for arg in [*item.args.args, *item.args.kwonlyargs]:
                if arg.arg == "config" and arg.annotation is not None:
                    return _annotation_name(arg.annotation)
    return None


def _longest_prefix_match(model_name: str, config_names: list[str]) -> str | None:
    """Return the config name sharing the longest common prefix with the model name."""
    best_name: str | None = None
    best_len = 0
    for name in config_names:
        shared = 0
        for model_char, config_char in zip(model_name, name):
            if model_char != config_char:
                break
            shared += 1
        if shared > best_len:
            best_len = shared
            best_name = name
    return best_name


def _resolve_config_class_name(model_node: ast.ClassDef, config_names: list[str]) -> str | None:
    """Resolve the config class a model class points to, most explicit signal first."""
    config_value = _get_class_assignments(model_node).get("config_class")
    if isinstance(config_value, (ast.Name, ast.Attribute)):
        return _simple_name(full_name(config_value))

    annotated = _config_annotation_name(model_node)
    if annotated is not None:
        return annotated

    return _longest_prefix_match(model_node.name, config_names)


def _declares_tie_word_embeddings(config_node: ast.ClassDef) -> bool:
    if "tie_word_embeddings" in _get_class_assignments(config_node):
        return True
    for item in config_node.body:
        if (
            isinstance(item, ast.AnnAssign)
            and isinstance(item.target, ast.Name)
            and item.target.id == "tie_word_embeddings"
        ):
            return True
        if isinstance(item, ast.FunctionDef) and item.name == "__init__":
            if "tie_word_embeddings" in _function_argument_names(item):
                return True
    return False


def _collect_config_classes(companion_files: list[Path]) -> dict[str, ast.ClassDef]:
    """Map config class name -> ClassDef across companion files (first file wins on clash)."""
    config_classes: dict[str, ast.ClassDef] = {}
    for cfg_path in companion_files:
        try:
            cfg_tree = ast.parse(cfg_path.read_text(encoding="utf-8"), filename=str(cfg_path))
        except (OSError, SyntaxError, ValueError):
            continue
        for node in cfg_tree.body:
            if isinstance(node, ast.ClassDef) and node.name not in config_classes:
                config_classes[node.name] = node
    return config_classes


