    if not file_path.name.startswith(("modeling_", "modular_")):
        return []

    # Imported lazily to avoid a circular import while mlinter discovers this module.
    from .mlinter import _find_companion_files

    config_classes = _collect_config_classes(_find_companion_files(file_path))
    if not config_classes:
        return []
    config_names = list(config_classes)

    violations: list[Violation] = []
    flagged_configs: set[str] = set()
    for node in iter_pretrained_classes(tree, source_lines, RULE_ID):
        if not _has_nonempty_tied_weights_keys(node):
            continue

        config_name = _resolve_config_class_name(node, config_names)
        if config_name is None or config_name in flagged_configs:
            continue
        config_node = config_classes.get(config_name)
        if config_node is None:
            continue

        # Only configs that directly inherit PreTrainedConfig are expected to own the flag;
        # configs inheriting another <...>Config delegate it to their parent.
        if not _is_direct_pretrained_config_subclass(config_node):
            continue
        if _declares_tie_word_embeddings(config_node):
            continue

        flagged_configs.add(config_name)
        violations.append(
            Violation(
                file_path=file_path,
                line_number=node.lineno,
                message=(
                    f"{RULE_ID}: {node.name} declares _tied_weights_keys but its config {config_name} "
                    "is missing a tie_word_embeddings flag; add it so weight tying can be disabled."
                ),
            )
        )

    return violations
